import {getSession} from "@/lib/auth"; import {query} from "@/lib/db"; import {redirect,notFound} from "next/navigation"; import {Brand} from "@/components/Brand"; import {LogoutButton,BackButton} from "@/components/AdminControls"; import ContentManager from "@/components/ContentManager";
export default async function ContentPage({params}:{params:Promise<{courseId:string}>}){const s=await getSession();if(!s||s.role!=="admin")redirect("/login");const{courseId}=await params;const r=await query(`SELECT id,title FROM courses WHERE id=$1`,[courseId]);if(!r.rowCount)notFound();const c=r.rows[0] as any;return <div className="dashboard"><aside className="sidebar"><Brand/><nav><a href="/admin">⌂ Dashboard</a><a href="/admin/courses">▦ Courses</a><a className="active" href={`/admin/content/${courseId}`}>◈ Content CMS</a><a>◉ Students</a><a>◉ Teachers</a><a>₹ Payments</a><a>☑ Tests</a><a>● Feedback</a><a>◫ Reports</a><a>⚙ Settings</a></nav><LogoutButton/></aside><main className="main"><div className="section-head"><div><span className="eyebrow">CONTENT MANAGEMENT</span><h1>{String(c.title)}</h1><p className="muted">Subjects → chapters → lessons → media, tests and assignments.</p></div><BackButton fallback="/admin/courses"/></div><ContentManager courseId={courseId}/></main></div>}
